#!/usr/bin/env python3
# Generated By: Claude Code (Claude Opus 4.7)
"""Render post-validation findings to a structured JSON document plus two
markdown files at the chosen output directory.

This is the only step that:
- Maps categorical dimensions to severity buckets via deterministic rules
- Assigns finding IDs (C0.., I0.., S0.., N0..) in stable per-bucket order

Intermediate JSON in the pipeline carries no severity labels and no IDs.
"""

import argparse
import json
import logging
import re
import sys
from pathlib import Path

import jsonschema

logger = logging.getLogger("render-review")

SKILL_ROOT = Path(__file__).resolve().parent.parent
PLUGIN_ROOT = SKILL_ROOT.parent.parent
SCHEMAS_DIR = SKILL_ROOT / "schemas"

# Add plugin root to sys.path so `scripts.envelope` is importable when this
# script runs as a subprocess.
sys.path.insert(0, str(PLUGIN_ROOT))
from scripts.envelope import (  # noqa: E402
    SEVERITY_BUCKETS,
    review_file_basename,
    assign_bucket,
    assign_ids_per_bucket,
    build_envelope,
    format_locations_block,
    format_validation_error,
    load_run_report_file,
    load_stage_dir,
    validate_envelope,
)

SOURCE = "review"

BUCKET_PREFIX = {
    "critical": "C",
    "important": "I",
    "suggestion": "S",
    "needs-review": "N",
}

BUCKET_ORDER = list(SEVERITY_BUCKETS)


def assign_buckets_and_ids(findings: list[dict], scoring: str = "categorical") -> list[dict]:
    if scoring == "simple":
        # Simple mode: severity comes directly from the agents/verdicts;
        # low confidence lands in needs-review instead of a rubric mapping.
        annotated = [
            {
                **f,
                "severity": "needs-review"
                if f.get("confidence") == "low"
                else f["severity"],
            }
            for f in findings
        ]
    else:
        annotated = [{**f, "severity": assign_bucket(f)} for f in findings]
    return assign_ids_per_bucket(
        annotated,
        bucket_order=BUCKET_ORDER,
        prefix_map=BUCKET_PREFIX,
    )


def _format_finding_block(f: dict, level: int = 4) -> str:
    locations = format_locations_block(f["locations"])
    if "runtime_scope" in f:
        ratings = (
            f"**Dimensions:** runtime_scope={f['runtime_scope']}, "
            f"failure_mode={f['failure_mode']}, "
            f"evidence_quality={f['evidence_quality']}, "
            f"trace_origin={f['trace_origin']}, "
            f"effort_to_fix={f['effort_to_fix']}"
        )
    else:
        ratings = f"**Confidence:** {f['confidence']}"
    return (
        f"{'#' * level} {f['id']}: {f['title']}\n\n"
        f"**Locations:**\n{locations}\n\n"
        f"{ratings}\n\n"
        f"**Issue:** {f['issue']}\n\n"
        f"**Why it matters:** {f['why_it_matters']}\n\n"
        f"**Suggested fix:** {f['suggested_fix']}\n"
    )


def _bucket_title(bucket: str) -> str:
    """'needs-review' -> 'Needs Review'. Also the supplementary heading text."""
    return bucket.replace("-", " ").title()


def _concern_anchor(concern_slug: str) -> str:
    """Anchor of the supplementary `### <Concern>` heading for this slug.

    Concern slugs are single lowercase words (the concern_slug enum), so the
    GitHub-style anchor of the title-cased heading is the slug itself.
    """
    return concern_slug


def _concern_breakdown_table(findings: list[dict], supp_path: str) -> str:
    """Concern x severity counts for the findings the main file does not inline.

    Replaces a bare total, which said nothing about where the work is. Each
    concern links to its section in the supplementary file.
    """
    counts: dict[str, dict[str, int]] = {}
    for f in findings:
        row = counts.setdefault(f["concern_slug"], {"suggestion": 0, "needs-review": 0})
        row[f["severity"]] += 1

    lines = ["| Concern | Suggestion | Needs review |", "|---|---|---|"]
    for concern in sorted(counts):
        row = counts[concern]
        link = f"[{concern.title()}]({supp_path}#{_concern_anchor(concern)})"
        lines.append(f"| {link} | {row['suggestion']} | {row['needs-review']} |")
    totals = (
        sum(r["suggestion"] for r in counts.values()),
        sum(r["needs-review"] for r in counts.values()),
    )
    lines.append(f"| **Total** | **{totals[0]}** | **{totals[1]}** |")
    return "\n".join(lines) + "\n"


STEP_MARK = {"ok": "ok", "degraded": "DEGRADED", "skipped": "skipped", "failed": "FAILED"}

# Issue kinds that record a pipeline decision rather than a failure.
DECISION_KINDS = frozenset({"finding_removed", "finding_truncated"})


def _run_report_section(rendered: dict) -> list[str]:
    """Render the run report and operational issues.

    Both live in the main file, above the findings: a review that lost a
    stage is not the same review as one that did not, and reading the
    findings without knowing that is the failure mode this replaces.
    """
    parts: list[str] = []
    report = rendered.get("run_report")
    issues = rendered.get("issues") or []
    if not report and not issues:
        return parts

    parts.append("## Run Report\n")
    if report:
        headline = {
            "ok": "Every pipeline step completed.",
            "degraded": "Some pipeline steps did not complete in full — "
            "findings below may be incomplete or unvalidated.",
            "failed": "A pipeline step failed.",
        }.get(report.get("status", ""), "")
        parts.append(f"**Status:** `{report.get('status', 'unknown')}` — {headline}\n")
        parts.append("| Step | Status | Detail |")
        parts.append("|---|---|---|")
        for step in report.get("steps", []):
            mark = STEP_MARK.get(step["status"], step["status"])
            detail = (step.get("detail") or "").replace("|", "\\|").replace("\n", " ")
            parts.append(f"| {step['step']} | {mark} | {detail} |")
        parts.append("")

    # Deliberate, successful pipeline decisions are not failures. Listing a
    # working diff-scope filter beside a dead sub-agent trains the reader to
    # skim the section, which is exactly what it exists to prevent.
    decisions = [i for i in issues if i["kind"] in DECISION_KINDS]
    failures = [i for i in issues if i["kind"] not in DECISION_KINDS]

    for heading, group, blurb in (
        ("Operational Issues", failures,
         "Something the run could not do. Findings may be incomplete."),
        ("Pipeline Decisions", decisions,
         "Deliberate choices, recorded for audit. Not failures."),
    ):
        if not group:
            continue
        parts.append(f"### {heading} ({len(group)})\n")
        parts.append(f"{blurb}\n")
        for issue in group:
            component = issue.get("source_component")
            where = f" (`{component}`)" if component else ""
            parts.append(
                f"- **{issue['severity']}** `{issue['kind']}`{where}: {issue['message']}"
            )
        parts.append("")
    return parts


def render_main_markdown(rendered: dict, project_name: str, scope_slug: str) -> str:
    """Render the main findings markdown: TL;DR, critical/important inline, suggestions/needs-review by reference."""
    findings = rendered["findings"]
    by_bucket = {b: [f for f in findings if f["severity"] == b] for b in BUCKET_ORDER}

    base = file_basename(scope_slug)
    supp_path = f"{base}-supplementary.md"

    parts: list[str] = []
    parts.append(f"# Code Review: {project_name}\n")
    parts.append("## TL;DR\n")
    counts = (
        f"{len(by_bucket['critical'])} critical, "
        f"{len(by_bucket['important'])} important, "
        f"{len(by_bucket['suggestion'])} suggestion, "
        f"{len(by_bucket['needs-review'])} needs-review."
    )
    parts.append(f"{counts}\n")
    parts.extend(_run_report_section(rendered))
    parts.append("## Findings\n")
    parts.append("### Critical\n")
    if by_bucket["critical"]:
        for f in by_bucket["critical"]:
            parts.append(_format_finding_block(f))
    else:
        parts.append("No critical issues identified.\n")

    parts.append("### Important\n")
    if by_bucket["important"]:
        for f in by_bucket["important"]:
            parts.append(_format_finding_block(f))
    else:
        parts.append("No important issues identified.\n")

    parts.append("### Suggestions and Needs Review\n")
    deferred = by_bucket["suggestion"] + by_bucket["needs-review"]
    if deferred:
        parts.append(
            f"Detailed in the [supplementary review]({supp_path}#detailed-analysis), "
            "grouped by concern:\n"
        )
        parts.append(_concern_breakdown_table(deferred, supp_path))
    else:
        parts.append("No suggestions or low-confidence findings.\n")

    return "\n".join(parts)


def render_supplementary_markdown(
    rendered: dict, project_name: str, scope_slug: str
) -> str:
    """Render the supplementary markdown: decomposition, detailed analysis by concern, suggestions, and needs-review."""
    findings = rendered["findings"]
    by_bucket = {b: [f for f in findings if f["severity"] == b] for b in BUCKET_ORDER}

    parts: list[str] = []
    parts.append(f"# Code Review (Supplementary): {project_name}\n")

    parts.append("## Decomposition\n")
    if rendered.get("decomposition"):
        for d in rendered["decomposition"]:
            scope = json.dumps(d.get("dimension_scope", {}), sort_keys=True)
            name = d["dimension_name"]
            slug = d["dimension_slug"]
            parts.append(f"- **{name}** (`{slug}`): {scope}")
        parts.append("")
    else:
        parts.append("(no decomposition recorded)\n")

    parts.append("## Detailed Analysis\n")
    by_concern: dict[str, list[dict]] = {}
    for f in findings:
        by_concern.setdefault(f["concern_slug"], []).append(f)
    if by_concern:
        # Concern first, severity second. Critical/important are repeated here
        # from the main file on purpose: reading one concern end to end is the
        # point of this section, and it breaks if its top findings are missing.
        for concern in sorted(by_concern):
            parts.append(f"### {concern.title()}\n")
            for bucket in BUCKET_ORDER:
                in_bucket = [f for f in by_concern[concern] if f["severity"] == bucket]
                if not in_bucket:
                    continue
                parts.append(f"#### {_bucket_title(bucket)}\n")
                for f in in_bucket:
                    parts.append(_format_finding_block(f, level=5))
    else:
        parts.append("(no findings to detail)\n")

    observations = (rendered.get("supplementary") or {}).get(
        "cross_cutting_observations", []
    )
    if observations:
        parts.append("## Cross-Cutting Observations\n")
        for obs in observations:
            parts.append(f"- (`{obs['agent']}`) {obs['text']}")
        parts.append("")

    return "\n".join(parts)


def file_basename(scope_slug: str) -> str:
    """Return the filename stem ``Findings-review[-<scope-slug>]``."""
    return review_file_basename(scope_slug)


def intent_file_basename(scope_slug: str) -> str:
    """Return the filename stem ``Findings-intent[-<scope-slug>]``.

    Carries the same slug as the findings files so reviews of two PRs in one
    repo do not overwrite each other's record of what they were judged
    against.
    """
    return f"Findings-intent-{scope_slug}" if scope_slug else "Findings-intent"


def render_intent_markdown(rendered: dict, project_name: str) -> str:
    """Render the intent the review ran with — including its absence.

    A file that says "none supplied" is the point: intent missing is the
    normal case today, and a review that silently invented a purpose for the
    code is not distinguishable from one that was told the purpose unless
    something writes it down.
    """
    parts = [f"# Review Intent: {project_name}\n"]
    intent = rendered.get("intent")
    if intent:
        parts.append(
            "What the lens and selector agents were told this change exists "
            "for. Findings were judged against this.\n"
        )
        parts.append(intent.rstrip() + "\n")
    else:
        parts.append(
            "**No intent was supplied.** Every lens judged this code against "
            "a purpose it inferred from the code itself, so a finding may "
            "contradict a deliberate decision this review never saw, and a "
            "requirement the change silently dropped could not be detected.\n"
        )
        parts.append(
            "Supply it by passing `--intent-file` to the orchestrator: the "
            "PR or issue description, the acceptance criteria, or a sentence "
            "saying what the change is for.\n"
        )
    return "\n".join(parts)


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--input-dir",
        type=Path,
        required=True,
        help="stage directory with _envelope.json + per-finding files",
    )
    parser.add_argument(
        "--out-dir",
        type=Path,
        required=True,
        help="directory for output files (typically the project root)",
    )
    parser.add_argument(
        "--project-name", required=True, help="project name used in output filenames"
    )
    parser.add_argument(
        "--scope-slug",
        default="",
        help="optional slug appended to filenames (PR number, theme, etc.)",
    )
    parser.add_argument(
        "--scoring",
        choices=["categorical", "simple"],
        default="categorical",
        help="scoring mode of the pipeline that produced the input findings",
    )
    parser.add_argument(
        "--debug",
        action="store_true",
        help="verbose diagnostic logging to stderr",
    )
    parser.add_argument(
        "--quiet",
        action="store_true",
        help="suppress the success summary line on stdout",
    )
    parser.add_argument(
        "--run-id",
        default="",
        help=(
            "orchestrator run id, recorded in the envelope so a findings file "
            "traces back to its agents after .tmp-review/ is wiped"
        ),
    )
    parser.add_argument(
        "--run-report",
        type=Path,
        default=None,
        help=(
            "JSON run report from the orchestrator (which pipeline steps ran "
            "and how each ended); embedded in the envelope and rendered into "
            "the main markdown"
        ),
    )
    parser.add_argument(
        "--intent-file",
        type=Path,
        default=None,
        help=(
            "file holding why the reviewed thing exists, as the agents were "
            "given it; embedded in the envelope and rendered to "
            "Findings-intent[-<scope-slug>].md. Omitted means none was "
            "available, which that file then says"
        ),
    )
    parser.add_argument(
        "--orchestrating-session-id",
        default="",
        help=(
            "Claude Code session that launched the run; a join key for "
            "telemetry, not a cost (that session's spend is not in costs.json)"
        ),
    )
    args = parser.parse_args(argv)

    if args.scope_slug and not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,30}", args.scope_slug):
        print(
            f"error: --scope-slug must match [a-z0-9][a-z0-9-]{{0,30}}: {args.scope_slug!r}",
            file=sys.stderr,
        )
        return 2

    logging.basicConfig(
        level=logging.DEBUG if args.debug else logging.INFO,
        format="%(levelname)s: %(message)s",
        stream=sys.stderr,
    )
    logger.debug("input-dir=%s out-dir=%s project-name=%s", args.input_dir, args.out_dir, args.project_name)

    if not args.input_dir.is_dir():
        logger.error("input directory not found: %s", args.input_dir)
        return 1

    try:
        envelope, findings = load_stage_dir(args.input_dir)
    except FileNotFoundError:
        logger.error("_envelope.json not found in %s", args.input_dir)
        return 1
    except (json.JSONDecodeError, ValueError) as exc:
        logger.error("could not read stage directory %s: %s", args.input_dir, exc)
        return 1

    try:
        run_report = load_run_report_file(args.run_report)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        logger.error("could not read --run-report %s: %s", args.run_report, exc)
        return 1

    intent = None
    if args.intent_file is not None:
        try:
            intent = args.intent_file.read_text(encoding="utf-8").strip() or None
        except OSError as exc:
            logger.error("could not read --intent-file %s: %s", args.intent_file, exc)
            return 1

    rendered_findings = assign_buckets_and_ids(findings, scoring=args.scoring)
    observations = envelope.get("cross_cutting_observations", [])
    rendered = build_envelope(
        source=SOURCE,
        project=envelope.get("project", {"name": args.project_name}),
        decomposition=envelope.get("decomposition", []),
        findings=rendered_findings,
        issues=envelope.get("issues", []),
        scoring="simple" if args.scoring == "simple" else None,
        run_id=args.run_id or None,
        orchestrating_session_id=args.orchestrating_session_id or None,
        run_report=run_report,
        intent=intent,
        supplementary={"cross_cutting_observations": observations}
        if observations
        else None,
    )

    try:
        validate_envelope(rendered)
    except jsonschema.ValidationError as exc:
        logger.error("%s", format_validation_error(exc, "review"))
        return 1

    args.out_dir.mkdir(parents=True, exist_ok=True)
    base = file_basename(args.scope_slug)
    json_path = args.out_dir / f"{base}.json"
    md_main_path = args.out_dir / f"{base}.md"
    md_supp_path = args.out_dir / f"{base}-supplementary.md"

    with json_path.open("w", encoding="utf-8") as fh:
        json.dump(rendered, fh, indent=2)
        fh.write("\n")
    md_main_path.write_text(
        render_main_markdown(rendered, args.project_name, args.scope_slug),
        encoding="utf-8",
    )
    md_supp_path.write_text(
        render_supplementary_markdown(rendered, args.project_name, args.scope_slug),
        encoding="utf-8",
    )
    md_intent_path = args.out_dir / f"{intent_file_basename(args.scope_slug)}.md"
    md_intent_path.write_text(
        render_intent_markdown(rendered, args.project_name),
        encoding="utf-8",
    )

    issues_count = len(rendered.get("issues") or [])
    if not args.quiet:
        print(
            f"render: wrote {json_path}, {md_main_path}, {md_supp_path}, "
            f"{md_intent_path} ({issues_count} issue(s) recorded)"
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
